1	package world
2	
3	import (
4		"fmt"
5		"sort"
6	)
7	
8	// BlockerKind 表示升级阻碍的类型。
9	type BlockerKind string
10	
11	const (
12		// BlockerLocation 表示角色所在地点在目标规则中已不存在。
13		BlockerLocation BlockerKind = "location"
14		// BlockerItem 表示角色携带的某种物品在目标规则中已不被允许。
15		BlockerItem BlockerKind = "item"
16		// BlockerLimit 表示角色携带总量超过目标规则给出的上限。
17		BlockerLimit BlockerKind = "limit"
18	)
19	
20	// Blocker 描述一条“目标规则无法原样承接当前角色状态”的具体阻碍。
21	type Blocker struct {
22		// Character 是受阻碍的角色标识。
23		Character string
24		// Kind 是阻碍类型。
25		Kind BlockerKind
26		// Location 是缺失的地点（Kind 为 BlockerLocation 时有值）。
27		Location string
28		// Item 是被移除的物品种类（Kind 为 BlockerItem 时有值）。
29		Item string
30		// Total 是角色当前携带总量（Kind 为 BlockerLimit 且 TotalOverflow
31		// 为 false 时有值，此时它就是真实总量）。
32		Total int
33		// TotalOverflow 表示真实携带总量超出 int 能表示的范围（来源规则未设
34		// 上限时可能出现）：此时 Total 不代表实际总量，调用方应改用
35		// TotalText 给出的完整十进制真实总量。
36		TotalOverflow bool
37		// TotalText 是真实携带总量的完整十进制表示（仅 TotalOverflow 为
38		// true 时有值）。
39		TotalText string
40		// Limit 是目标规则给出的新上限（Kind 为 BlockerLimit 时有值）。
41		Limit int
42	}
43	
44	// UpgradeCheck 描述对槽当前最新记录与目标规则的兼容性检查结果。
45	type UpgradeCheck struct {
46		// RecordID 是所检查的来源记录标识（槽当前最新记录）。
47		RecordID RecordID
48		// OldVersion 是来源记录的规则版本。
49		OldVersion string
50		// TargetVersion 是目标规则版本。
51		TargetVersion string
52		// Compatible 表示目标规则能否原样承接当前角色状态。
53		Compatible bool
54		// Blockers 是全部阻碍，按角色标识、物品标识排序；重复检查输出顺序一致。
55		Blockers []Blocker
56	}
57	
58	// UpgradeResult 是升级的返回结果。
59	type UpgradeResult struct {
60		// Check 是对当前来源记录与目标规则的兼容性检查结果。
61		Check UpgradeCheck
62		// Record 是成功时新记录的元信息；被阻碍时为零值。
63		Record RecordInfo
64	}
65	
66	// checkCompatibility 计算用 target 规则原样承接 st 中全部角色状态的阻碍。
67	//
68	// 兼容只判断能否原样承接当前角色状态：每个角色所在地点仍存在，已列出的
69	// 物品种类仍被允许（数量为零也算），各角色携带总量不超过目标上限（按真实
70	// 总量精确求和，不因回绕放过超限；真实总量超出 int 范围时阻碍置
71	// TotalOverflow 并以 TotalText 给出完整十进制总量）；目标中没有该角色上限
72	// 时表示不设上限。允许删去无人所在的地点、不再出现的物品种类或旧连通关系，
73	// 也允许增加内容。升级后移动和物品变化按目标规则处理。
74	func checkCompatibility(st State, target Rules) []Blocker {
75		locSet := make(map[string]struct{}, len(target.Locations))
76		for _, l := range target.Locations {
77			locSet[l] = struct{}{}
78		}
79		kindSet := make(map[string]struct{}, len(target.ItemKinds))
80		for _, k := range target.ItemKinds {
81			kindSet[k] = struct{}{}
82		}
83		var blockers []Blocker
84		for _, ch := range st.Characters {
85			if _, ok := locSet[ch.Location]; !ok {
86				blockers = append(blockers, Blocker{
87					Character: ch.ID,
88					Kind:      BlockerLocation,
89					Location:  ch.Location,
90				})
91			}
92			for _, it := range ch.Items {
93				if _, ok := kindSet[it.Item]; !ok {
94					blockers = append(blockers, Blocker{
95						Character: ch.ID,
96						Kind:      BlockerItem,
97						Item:      it.Item,
98					})
99				}
100			}
101			// 携带上限按真实总量判断，与建立/重建世界、提交物品变化共用同一
102			// 口径（精确求和不因回绕放过超限，目标中没有该角色上限时表示不设
103			// 上限）。真实总量能用 int 表示时沿用 Total 字段；超出 int 范围时
104			// 置 TotalOverflow 并给出完整十进制 TotalText，绝不返回回绕值。
105			if limit, ok := target.CarryLimits[ch.ID]; ok {
106				total := carryTotal(ch.Items)
107				if totalExceedsLimit(total, limit) {
108					b := Blocker{
109						Character: ch.ID,
110						Kind:      BlockerLimit,
111						Limit:     limit,
112					}
113					if total.Cmp(maxIntBig) <= 0 {
114						b.Total = int(total.Int64())
115					} else {
116						b.TotalOverflow = true
117						b.TotalText = total.String()
118					}
119					blockers = append(blockers, b)
120				}
121			}
122		}
123		// 同类问题按角色标识、物品标识排序；location/limit 阻碍没有物品标识，
124		// 以空物品标识参与排序，保证重复检查输出顺序一致。跨类别按
125		// location、item、limit 的自然顺序分组，便于阅读。
126		kindRank := func(k BlockerKind) int {
127			switch k {
128			case BlockerLocation:
129				return 0
130			case BlockerItem:
131				return 1
132			case BlockerLimit:
133				return 2
134			}
135			return 3
136		}
137		sort.SliceStable(blockers, func(i, j int) bool {
138			if blockers[i].Character != blockers[j].Character {
139				return blockers[i].Character < blockers[j].Character
140			}
141			if blockers[i].Kind != blockers[j].Kind {
142				return kindRank(blockers[i].Kind) < kindRank(blockers[j].Kind)
143			}
144			return blockers[i].Item < blockers[j].Item
145		})
146		return blockers
147	}
148	
149	// checkUpgradeLocked 在调用方已持锁（共享或排他均可）的前提下读取并校验
150	// 槽当前最新记录，计算目标规则的兼容性。返回检查结果与来源记录信封。
151	func (a *Archive) checkUpgradeLocked(slot string, acceptedVersions []string, target Rules) (UpgradeCheck, *envelope, error) {
152		latest, err := a.readLatestLocked(slot)
153		if err != nil {
154			return UpgradeCheck{}, nil, err
155		}
156		env, err := a.loadAndVerifyLocked(latest)
157		if err != nil {
158			if ce, ok := err.(*CorruptError); ok {
159				ce.Slot = slot
160			}
161			return UpgradeCheck{}, nil, err
162		}
163		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
164			return UpgradeCheck{}, nil, &VersionRejectedError{
165				Slot:     slot,
166				Record:   latest,
167				Version:  env.State.Rules.Version,
168				Accepted: append([]string(nil), acceptedVersions...),
169			}
170		}
171		if target.Version == env.State.Rules.Version {
172			return UpgradeCheck{}, nil, &RuleError{Reason: "目标规则版本必须与来源记录版本不同"}
173		}
174		check := UpgradeCheck{
175			RecordID:      latest,
176			OldVersion:    env.State.Rules.Version,
177			TargetVersion: target.Version,
178		}
179		blockers := checkCompatibility(env.State, target)
180		check.Compatible = len(blockers) == 0
181		check.Blockers = blockers
182		return check, env, nil
183	}
184	
185	// CheckUpgrade 检查槽当前最新记录能否在目标规则下继续使用。
186	//
187	// 检查只读取来源记录并计算兼容性，不改变世界、历史或槽当前记录，也不会
188	// 替换记录中的规则。target 必须先满足规则自身的合法性要求，且版本与来源
189	// 记录不同（版本只按相等判断，不按数字大小限制升级）。
190	//
191	// 目标规则非法返回 *RuleError；版本相同返回 *RuleError；来源损坏返回
192	// *CorruptError；来源版本不在 acceptedVersions 内返回 *VersionRejectedError；
193	// 槽不存在沿用现有不存在错误。
194	func (a *Archive) CheckUpgrade(slot string, acceptedVersions []string, target Rules) (UpgradeCheck, error) {
195		if !validSlotName(slot) {
196			return UpgradeCheck{}, &NotFoundError{Slot: slot}
197		}
198		if err := validateRules(target); err != nil {
199			return UpgradeCheck{}, err
200		}
201		lock, err := acquireSharedLock(a.dir)
202		if err != nil {
203			return UpgradeCheck{}, err
204		}
205		defer lock.release()
206		check, _, err := a.checkUpgradeLocked(slot, acceptedVersions, target)
207		if err != nil {
208			return UpgradeCheck{}, err
209		}
210		return check, nil
211	}
212	
213	// Upgrade 在检查通过后用目标规则生成一条新记录。
214	//
215	// 传入与 CheckUpgrade 相同的条件，并带调用方预期的最新记录标识 expected。
216	// 提交时在排他锁下重新判断当前来源：仍有阻碍则返回相同的阻碍信息并拒绝
217	// 写入；expected 为空或已不是该槽最新记录时返回现有冲突错误。
218	//
219	// 被拒绝的升级不增加历史记录，也不改变槽当前记录。成功后槽增加一条完整
220	// 的新记录，以被升级记录为父，保存目标规则；种子、时间片、角色位置及
221	// 物品数量和排列保持原样。并发升级或升级与普通覆盖竞争时，只有 expected
222	// 与最新记录一致的一个成功，其余收到冲突。
223	func (a *Archive) Upgrade(slot string, acceptedVersions []string, target Rules, expected RecordID) (UpgradeResult, error) {
224		if !validSlotName(slot) {
225			return UpgradeResult{}, &NotFoundError{Slot: slot}
226		}
227		if err := validateRules(target); err != nil {
228			return UpgradeResult{}, err
229		}
230		if expected == "" {
231			return UpgradeResult{}, &ConflictError{Slot: slot, Reason: "升级必须提供所依据的记录标识"}
232		}
233		lock, err := acquireLock(a.dir)
234		if err != nil {
235			return UpgradeResult{}, err
